// Shape the alternatives call, and decide up front whether this decline is even answerable.
const row = ($input.first().json || {});
const d = row.result || {};
const a = d.appointment || {};
const bad = row.error !== undefined ? 'db_unavailable'
  : !d.found ? 'booking_not_found'
  : d.status !== 'confirmed' ? 'not_confirmed'
  : !d.in_future ? 'already_started'
  : !d.still_theirs ? 'already_reassigned'
  : d.already_asked ? 'consent_already_pending'
  : null;
return [{ json: {
  // 23's arguments at the top level; everything else travels under _ctx.
  service_id: a.service_id || null, starts_at: a.starts_at_utc || null,
  ends_at: a.ends_at_utc || null, exclude_stylist_id: a.stylist_id || null,
  _ctx: { bad, appt: a },
} }];

// Choose the replacement to PROPOSE — and propose it, never apply it. The customer decides
// who touches their hair; a salon that silently swaps the person is a salon you leave.
const alts = ($input.first().json || {});
const ctx = ($('Build the alternatives request').first().json || {})._ctx || {};
const a = ctx.appt || {};
// Even a dead end emits ONE item, so the branch reaches the result node instead of ending
// silently and leaving the caller with nothing at all.
if (ctx.bad) {
  return [{ json: { _result: { ok: false, reason: ctx.bad }, _skip: true } }];
}
const list = (alts.ok && alts.data && alts.data.alternatives) ? alts.data.alternatives : [];
const pick = list[0] || null;
// Every notice becomes an item for the sender, and the verdict rides on the first of them.
function notify(result, pending, notices) {
  return notices.map((n, i) => ({ json: Object.assign({}, n,
    i === 0 ? { _result: result, _pending: pending } : {}) }));
}

if (!pick) {
  // Nobody free. Say so plainly, offer the two things that are actually possible, and put it
  // in front of a human — never invent a name to fill the gap.
  return notify({ ok: true, outcome: 'no_alternative', ref: a.ref }, null, [
      { appointment_id: a.id, recipient: 'client', kind: 'reassign_none',
        text: `About your ${a.service_name} on ${a.starts_at_local}: ${a.stylist_name} can no longer make it, `
            + `and nobody else is free at that time. Would you like to move it to another slot, or cancel? `
            + `Reply here and we will sort it out.` },
      { appointment_id: a.id, recipient: 'manager', kind: 'reassign_none_manager',
        text: `No cover for ${a.ref}: ${a.service_name}, ${a.starts_at_local}, ${a.stylist_name} declined `
            + `and no alternative stylist is free. Client ${a.client_name} has been asked to reschedule or cancel.` },
  ]);
}
return notify({ ok: true, outcome: 'consent_requested', ref: a.ref, proposed: pick.stylist_name },
  { user_key: a.user_key, json: JSON.stringify({
      kind: 'reassign', ref: a.ref, appointment_id: a.id,
      from_stylist_id: a.stylist_id, from_stylist_name: a.stylist_name,
      to_stylist_id: pick.stylist_id, to_stylist_name: pick.stylist_name,
      service_name: a.service_name, starts_at_local: a.starts_at_local,
      summary: `move ${a.ref} to ${pick.stylist_name}` }) },
  [
    { appointment_id: a.id, recipient: 'client', kind: 'reassign_consent',
      text: `Hi ${a.client_name} — ${a.stylist_name} can't make your ${a.service_name} on ${a.starts_at_local}. `
          + `${pick.stylist_name}${pick.title ? ', our ' + pick.title.toLowerCase() + ',' : ''} is free at the same time `
          + `and is held to exactly the same standard as the rest of our team. `
          + `Shall I move you to ${pick.stylist_name}? Reply yes, or no if you would rather keep `
          + `${a.stylist_name} and find another time.` },
  ]);

// A Postgres node REPLACES the item with its own result, so the notices written by "Decide"
// are gone by the time we reach the sender. Recover them from the node that produced them —
// the standard way to carry fields across a node that rewrites the item.
return $('Decide the replacement').all();

const d = $('Decide the replacement').first().json || {};
let sends = [];
try { sends = $('Tell the client (and the manager)').all().map(s => s.json || {}); } catch (e) { sends = []; }
return [{ json: Object.assign({}, d._result || { ok: false, reason: 'unknown' },
                              { notices: sends.map(s => `${s.recipient}/${s.kind}:${s.reason}`) }) }];
